//! Edit staging and immutable source publication share real native budgets.
use super::*;
#[test]
fn character_splice_no_slot_copy_and_storage_refusal_keep_sources_and_charge_actual_cow(){
 for factory in ["createTextNode","createComment"]{
 let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);let nodes=doc.nodes.len();page.state.node_limit=nodes;assert_eq!(page.console_eval(&mut doc,&mut forms,&format!("var owner=new Document(),source=owner.{factory}('held');")).errors,0);let Value::Host(source)=page.runtime.execute("source",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("source")};assert!(node_index(source).is_none());page.begin_job();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits,b.doc.nodes.len());let direct=matches!(b.state.inert_documents.node(source).unwrap().kind,Kind::Text(_));let old_capacity=b.character_data_source(source).unwrap().capacity();let copies=b.state.copy_work;let limit=b.state.retained_limit;let args=[Value::String(" grow".into())];b.state.copy_work=0;assert!(b.native_character_edit(source,"\0CharacterData.appendData",&args).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits,b.doc.nodes.len()),before);b.state.copy_work=copies;let edit=b.native_character_edit(source,"\0CharacterData.appendData",&args).unwrap();b.state.retained_limit=before.0;assert!(b.write_character_splice(source,edit.value,edit.offset,edit.removed,edit.inserted).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits,b.doc.nodes.len()),before);assert_eq!(b.character_data_source(source).unwrap().scalar().unwrap(),"held");b.state.retained_limit=limit;b.state.copy_work=copies;let edit=b.native_character_edit(source,"\0CharacterData.appendData",&args).unwrap();b.write_character_splice(source,edit.value,edit.offset,edit.removed,edit.inserted).unwrap();assert_eq!(b.character_data_source(source).unwrap().scalar().unwrap(),"held grow");assert_eq!(b.doc.nodes.len(),nodes);assert_eq!(b.state.inert_documents.entries.len(),before.2);if direct{assert_eq!(b.state.inert_documents.generated.len(),before.3);assert_eq!(b.state.retained,before.0-old_capacity+b.character_data_source(source).unwrap().capacity()+b.state.inert_documents.backing_bytes()-before.1);}else{assert_eq!(b.state.inert_documents.generated.len(),before.3+1);let added=b.state.inert_documents.generated.last().unwrap();let payload=node_bytes(&added.node)+size_of::<Node>()+2*size_of::<usize>();assert_eq!(b.state.retained,before.0+payload+b.state.inert_documents.backing_bytes()-before.1);}
}
}
